import {env} from 'cloudflare:workers';
import {getDb} from '../../../db';
import {responses} from '../../../db/schema';
import {eq} from 'drizzle-orm';
import {cors,tokenScope,SENDER} from '../../../lib/amp-guard.mjs';
export const dynamic='force-dynamic';
export function GET(){return Response.json({error:'POST required; opening a link never records a response.'},{status:405,headers:{Allow:'POST, OPTIONS','Cache-Control':'no-store'}});}
export function OPTIONS(request:Request){const h=cors(request);return new Response(null,{status:h?204:403,headers:h||{}});}
export async function POST(request:Request){
 const h=cors(request);if(!h)return Response.json({error:'Sender not allowed.'},{status:403});
 const e=env as any;
 const scope=await tokenScope(new URL(request.url).searchParams.get('token'),{email:e.AMP_EMAIL_HASH,qa_yes:e.AMP_QA_YES_HASH,qa_no:e.AMP_QA_NO_HASH},e.AMP_EXPIRES);
 if(!scope)return Response.json({error:'Invalid or expired test token.'},{status:403,headers:h});
 if(Number(request.headers.get('Content-Length')||0)>2048)return Response.json({error:'Request too large.'},{status:413,headers:h});
 let data;try{data=await request.formData();}catch{return Response.json({error:'Invalid form.'},{status:400,headers:h});}
 const choice=data.get('choice');if(choice!=='YES'&&choice!=='NO')return Response.json({error:'Choose YES or NO.'},{status:400,headers:h});
 const eventId='do2u3gjemi3tqljvsrj054ulas';
 const id='amp:'+scope+':'+eventId;
 const result=choice==='YES'?'YES recorded. Test classification only; production Preinspection automation remains disconnected.':'NO recorded. Test appointment classified as not a Preinspection.';
 const db=getDb();await db.insert(responses).values({id,userId:'amp-test:'+scope,email:SENDER,eventId,choice,createdAt:new Date().toISOString(),result}).onConflictDoNothing();
 const rows=await db.select().from(responses).where(eq(responses.id,id));if(rows.length!==1)throw new Error('Read-back failed');
 const saved=rows[0];if(saved.choice!==choice)return Response.json({error:'A different answer was already recorded. Original response preserved.',choice:saved.choice},{status:409,headers:h});
 return Response.json({message:saved.result,choice:saved.choice,recordedAt:saved.createdAt,testOnly:true},{headers:h});
}

