export const dynamic='force-dynamic';
const EVENT='do2u3gjemi3tqljvsrj054ulas';
export async function GET(){const user=await getChatGPTUser();if(!user)return Response.json({error:'Sign in to view responses.'},{status:401});const history=await getDb().select().from(responses).where(eq(responses.userId,user.userId));return Response.json({history},{headers:{'Cache-Control':'no-store'}});}
export async function POST(request:Request){
 const user=await getChatGPTUser();if(!user)return Response.json({error:'Sign in before confirming.'},{status:401});
 const origin=request.headers.get('origin');if(origin!==new URL(request.url).origin)return Response.json({error:'Invalid origin.'},{status:403});
 let body;try{body=await request.json();}catch{return Response.json({error:'Invalid request.'},{status:400});}
 if(body.choice!=='YES'&&body.choice!=='NO')return Response.json({error:'Choose YES or NO.'},{status:400});
 const result=body.choice==='YES'?'YES recorded. Isolated evaluation: REVIEW — fictional customer and address are not verified. No Striven Task created; no Calendar changes. Production engine was not invoked.':'NO recorded. Test classified as not a Preinspection. No downstream actions.';
 const row={id:user.userId+':'+EVENT+':'+body.choice,userId:user.userId,email:user.email,eventId:EVENT,choice:body.choice,createdAt:new Date().toISOString(),result};
 const db=getDb();await db.insert(responses).values(row).onConflictDoNothing();const saved=await db.select().from(responses).where(eq(responses.id,row.id));
 if(saved.length!==1)throw new Error('Response read-back failed');
 return Response.json({message:saved[0].result,saved:saved[0]},{headers:{'Cache-Control':'no-store'}});
}

