export const SENDER='pramodh@classicfireplace.ca';
export function cors(request){
 const h={'Cache-Control':'no-store','Vary':'Origin, AMP-Email-Sender'};
 const sender=request.headers.get('AMP-Email-Sender');
 const origin=request.headers.get('Origin');
 if(sender){if(sender!==SENDER)return null;h['AMP-Email-Allow-Sender']=SENDER;}
 else {if(!origin||new URL(request.url).searchParams.get('__amp_source_origin')!==SENDER)return null;
 h['AMP-Access-Control-Allow-Source-Origin']=SENDER;h['Access-Control-Expose-Headers']='AMP-Access-Control-Allow-Source-Origin';}
 if(origin){if(!['https://mail.google.com','https://amp.gmail.dev'].includes(origin))return null;h['Access-Control-Allow-Origin']=origin;}
 h['Access-Control-Allow-Methods']='POST, OPTIONS';h['Access-Control-Allow-Headers']='Content-Type, AMP-Email-Sender';return h;
}
export async function tokenScope(raw,hashes,expiry,now=Date.now()){
 if(!raw||!Number.isFinite(Date.parse(expiry))||now>=Date.parse(expiry))return null;
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw));
 const hash=Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');
 return Object.entries(hashes).find(([,v])=>v===hash)?.[0]||null;
}

