import assert from 'node:assert/strict';
import {cors,tokenScope,SENDER} from '../lib/amp-guard.mjs';
const req=(headers={},query='')=>new Request('https://test.invalid/api/amp'+query,{headers});
assert.equal(cors(req()),null);
assert.equal(cors(req({'AMP-Email-Sender':'attacker@example.com'})),null);
assert.equal(cors(req({'AMP-Email-Sender':SENDER}))['AMP-Email-Allow-Sender'],SENDER);
assert.equal(cors(req({Origin:'https://mail.google.com'},'?__amp_source_origin='+SENDER))['Access-Control-Allow-Origin'],'https://mail.google.com');
assert.equal(cors(req({Origin:'https://evil.invalid'},'?__amp_source_origin='+SENDER)),null);
assert.equal(cors(req({Origin:'https://mail.google.com'})),null);
const raw='test-token',hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw))),v=>v.toString(16).padStart(2,'0')).join('');
assert.equal(await tokenScope(raw,{email:hash},'2030-01-01',0),'email');
assert.equal(await tokenScope('wrong',{email:hash},'2030-01-01',0),null);
assert.equal(await tokenScope(raw,{email:hash},'2000-01-01'),null);
assert.equal(await tokenScope(raw,{email:hash},'invalid'),null);
console.log('10 AMP sender/CORS/token/expiry checks passed');

